-- GERADO por scripts/build-cidades.mjs. Não editar à mão.
-- Países, cidades do TSE com seção no exterior (1º turno de 2026) e locais de votação fora da cidade do TSE
-- (eleitorado por local de votação do TSE). Coordenadas: OpenStreetMap. Idempotente: também atualiza a produção
-- (pnpm exec supabase db query --linked -f supabase/seed.sql).

on conflict (code) do update set name = excluded.name, timezone = excluded.timezone;

on conflict (tse_code) do update set slug = excluded.slug, name = excluded.name, country_code = excluded.country_code, timezone = excluded.timezone, lat = excluded.lat, lon = excluded.lon, voters = excluded.voters, turnout = excluded.turnout, abstention_pct = excluded.abstention_pct, has_section = excluded.has_section, venue_name = excluded.venue_name, address = excluded.address, hours = excluded.hours, notes = excluded.notes, place_voters = excluded.place_voters, sort_order = excluded.sort_order;

on conflict (tse_code) do update set slug = excluded.slug, name = excluded.name, country_code = excluded.country_code, timezone = excluded.timezone, lat = excluded.lat, lon = excluded.lon, voters = excluded.voters, turnout = excluded.turnout, abstention_pct = excluded.abstention_pct, has_section = excluded.has_section, venue_name = excluded.venue_name, address = excluded.address, hours = excluded.hours, notes = excluded.notes, place_voters = excluded.place_voters, sort_order = excluded.sort_order, parent_id = excluded.parent_id;

-- Locais que já estiveram no site e não existem no TSE (Manchester, Hyannis).
update public.voting_cities set has_section = false where tse_code in ('99503-L1', '29416-L2');
